CREATE TABLE bill_control_links(record_id TEXT PRIMARY KEY REFERENCES records(id),booking_id TEXT NOT NULL REFERENCES booking_handovers(id),owner TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX bill_control_links_booking ON bill_control_links(owner,booking_id);
CREATE TABLE bill_control_readings(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES booking_handovers(id),owner TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES operation_documents(id),document_hash TEXT NOT NULL,status TEXT NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,result TEXT,error TEXT,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX bill_control_reading_active ON bill_control_readings(document_id) WHERE status='reading';
CREATE TABLE bill_control_decisions(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES booking_handovers(id),owner TEXT NOT NULL,fingerprint TEXT NOT NULL,subject TEXT NOT NULL,action TEXT NOT NULL,choice TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX bill_control_decisions_booking ON bill_control_decisions(owner,booking_id);
CREATE TABLE bill_control_requests(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES booking_handovers(id),record_id TEXT NOT NULL REFERENCES records(id),owner TEXT NOT NULL,revision INTEGER NOT NULL,kind TEXT NOT NULL,payload_hash TEXT NOT NULL,payload TEXT NOT NULL,fingerprint TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(record_id,kind,payload_hash,fingerprint));
CREATE TABLE bill_control_approvals(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES bill_control_requests(id),decision_hash TEXT NOT NULL,owner TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,revoked_at TEXT,revocation_reason TEXT);
CREATE TABLE bill_control_document_events(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES booking_handovers(id),owner TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES operation_documents(id),kind TEXT NOT NULL,related_id TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER bill_control_reading_insert AFTER INSERT ON bill_control_readings BEGIN UPDATE booking_handovers SET evidence_revision=evidence_revision+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER bill_control_reading_update AFTER UPDATE OF status,result ON bill_control_readings BEGIN UPDATE booking_handovers SET evidence_revision=evidence_revision+1 WHERE id=NEW.booking_id; END;
ALTER TABLE booking_handovers ADD COLUMN control_epoch INTEGER NOT NULL DEFAULT 0;
CREATE TRIGGER control_booking_epoch AFTER UPDATE OF data,revision,evidence_revision ON booking_handovers BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.id; END;
CREATE TRIGGER control_field_epoch AFTER UPDATE ON booking_field_operations BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_field_insert_epoch AFTER INSERT ON booking_field_operations BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_schedule_epoch AFTER UPDATE ON booking_schedules BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_schedule_insert_epoch AFTER INSERT ON booking_schedules BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_link_epoch AFTER INSERT ON bill_control_links BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_decision_epoch AFTER INSERT ON bill_control_decisions BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_event_epoch AFTER INSERT ON bill_control_document_events BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_record_epoch AFTER UPDATE OF revision,manual,extraction,fields,hash ON records BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id IN(SELECT booking_id FROM bill_control_links WHERE record_id=NEW.id); END;
CREATE TRIGGER control_vgm_insert_epoch AFTER INSERT ON booking_vgm_approvals BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
CREATE TRIGGER control_vgm_update_epoch AFTER UPDATE ON booking_vgm_approvals BEGIN UPDATE booking_handovers SET control_epoch=control_epoch+1 WHERE id=NEW.booking_id; END;
